using Microsoft.Extensions.Logging;

namespace Radish.Api.Tests.ErrorHandling;

internal sealed record TransportFrameworkEvent(string Assembly, string Type, string Method, string Source, int Id, string Name, LogLevel Level, string Code)
{
    public MethodInfo Generator => System.Reflection.Assembly.Load(Assembly).GetType(Type, true)!
        .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static)
        .Single(m => m.Name == Method && m.GetCustomAttribute<LoggerMessageAttribute>() != null);
}

